def episode_state_at(episodes, t):
    """Причинно: активный на момент t эпизод (start<=t<=end), его возраст (мин) и глубина до t включительно.
    Возраст/глубина считаются honestly только по данным <= t (используем полный эпизод — end известен
    только пост-фактум, поэтому для 'ещё идёт' берём эпизоды, у которых start<=t<=end, и глубину
    оцениваем по всему эпизоду; это небольшое послабление, отмечено в оговорках)."""
    for e in episodes:
        if e["start"] <= t <= e["end"]:
            return {"age_min": (t - e["start"]) / 60_000, "depth_bps": e["depth_bps"]}
    return None


def episodes_in_trailing(episodes, t, back_ms=MS_D):
    """Число эпизодов, чей интервал пересекается с [t-back_ms, t] (причинно — только начавшиеся <= t)."""
    return sum(1 for e in episodes if e["start"] <= t and e["end"] >= t - back_ms and e["start"] <= t)

